-- Rebuild Medina Book 3 lesson 15 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 60-65; lesson 15 continues at the top of page 65 before lessons 16-17.
-- Qur'anic strings and ﷺ symbols hidden by DOC control characters were transcribed literally from the visible PDF.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15';
  if old_rule_count <> 6 then raise exception 'Expected 6 generated Book 3 lesson 15 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '15', 'جَوَازِمُ الْمُضَارِعِ: الْجَازِمُ فِعْلَيْنِ (условные средства, управляющие двумя глаголами)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَدَوَاتُ الَّتِي تَجْزِمُ <span class="ar-tone-verb">فِعْلَيْنِ مُضَارِعَيْنِ</span> تُسَمَّى <span class="ar-tone-particle">أَدَوَاتِ الشَّرْطِ</span>. الْأَوَّلُ فِعْلُ الشَّرْطِ، وَالثَّانِي جَوَابُ الشَّرْطِ.</span><p class="rule-study-text">Средства условия управляют джазмом двух глаголов настоящего-будущего времени. Первый — глагол условия, второй — ответ условия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Условные средства и их назначение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَدَاةُ الشَّرْطِ</span><span class="rule-table-ru">условное средство</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُهَا</span><span class="rule-table-ru">вид и русский смысл</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنْ</span><span class="rule-table-ru">если</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-table-ru">частица</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِنْ تَزُرْنِي أَزُرْكَ.</span><span class="rule-table-ru">Если ты посетишь меня, я посещу тебя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِذْمَا</span><span class="rule-table-ru">если; когда бы ни</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-table-ru">частица</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذْمَا تَقُمْ أَقُمْ.</span><span class="rule-table-ru">Если ты встанешь, я встану.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَنْ</span><span class="rule-table-ru">кто</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمٌ لِلْعَاقِلِ</span><span class="rule-table-ru">имя для разумного существа</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَنْ يَغِبْ يُطْوَ قَيْدُهُ.</span><span class="rule-table-ru">Кто отсутствует, запись о нём сворачивается.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">что; что бы ни</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمٌ لِغَيْرِ الْعَاقِلِ</span><span class="rule-table-ru">имя для неразумного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَا تَزْرَعْ تَحْصُدْ.</span><span class="rule-table-ru">Что посеешь, то пожнёшь.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَهْمَا</span><span class="rule-table-ru">что бы ни</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمٌ لِغَيْرِ الْعَاقِلِ</span><span class="rule-table-ru">имя для неразумного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَهْمَا تَقُلْ أُصَدِّقْكَ. مَهْمَا تَقْرَأْ أَقْرَأْ.</span><span class="rule-table-ru">Что бы ты ни сказал, я поверю тебе. Что бы ты ни читал, я прочитаю.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَتَى</span><span class="rule-table-ru">когда бы ни</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمٌ لِلزَّمَانِ</span><span class="rule-table-ru">имя времени</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَتَى تُسَافِرْ أُسَافِرْ.</span><span class="rule-table-ru">Когда ты поедешь, я поеду.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-table-ru">где бы ни</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمٌ لِلْمَكَانِ</span><span class="rule-table-ru">имя места</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَيْنَمَا تُسَافِرْ أُسَافِرْ.</span><span class="rule-table-ru">Куда бы ты ни поехал, я поеду.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَيْثُ</span><span class="rule-table-ru">где бы ни</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِسْمٌ لِلْمَكَانِ</span><span class="rule-table-ru">имя места</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَيْثُمَا تَذْهَبْ يَرَكَ اللَّهُ.</span><span class="rule-table-ru">Куда бы ты ни пошёл, Аллах видит тебя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَيٌّ</span><span class="rule-table-ru">любой; какой бы ни</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمٌ بِحَسَبِ مَا تُضَافُ إِلَيْهِ</span><span class="rule-table-ru">значение определяется словом в идафе</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَيُّ طَالِبٍ يَجْتَهِدْ يَنْجَحْ.</span><span class="rule-table-ru">Какой бы студент ни усердствовал, он преуспеет.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَإِنْ تَعُودُوا نَعُدْ ﴾</span><span class="rule-example-ru">«Если вы вернётесь, то и Мы вернёмся».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-subject" dir="rtl" lang="ar">﴿ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ﴾</span><span class="rule-example-ru">«Кто боится Аллаха, тому Он создаёт выход».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-subject" dir="rtl" lang="ar">﴿ وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ ﴾</span><span class="rule-example-ru">«Какое бы добро вы ни совершили, Аллах знает его».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-nasb" dir="rtl" lang="ar">﴿ أَيْنَمَا تَكُونُوا يُدْرِكْكُمُ الْمَوْتُ ﴾</span><span class="rule-example-ru">«Где бы вы ни были, смерть настигнет вас».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Особенности أَيْنَ، حَيْثُ и أَيٌّ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَدَاةُ</span><span class="rule-table-ru">средство</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُلَاحَظَةُ</span><span class="rule-table-ru">замечание автора</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-table-ru">где</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَتَّصِلُ بِهَا كَثِيرًا مَا الزَّائِدَةُ لِلتَّوْكِيدِ</span><span class="rule-table-ru">к ней часто присоединяется усилительная добавочная «ма»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَيْنَمَا تُسَافِرْ أُسَافِرْ.</span><span class="rule-table-ru">Куда бы ты ни поехал, я поеду.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَيْثُ</span><span class="rule-table-ru">где</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا تَجْزِمُ إِلَّا إِذَا اتَّصَلَتْ بِهَا مَا الزَّائِدَةُ</span><span class="rule-table-ru">управляет джазмом только при присоединении добавочной «ма»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَيْثُمَا تَذْهَبْ يَرَكَ اللَّهُ.</span><span class="rule-table-ru">Куда бы ты ни пошёл, Аллах видит тебя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَيٌّ</span><span class="rule-table-ru">любой; какой бы ни</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُعْرَبُ بِحَسَبِ مَوْقِعِهَا</span><span class="rule-table-ru">изменяется по своему синтаксическому месту</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَيَّ كِتَابٍ تَقْرَأْ تَسْتَفِدْ. فِي أَيِّ يَوْمٍ تَزُرْنِي أُكْرِمْكَ.</span><span class="rule-table-ru">Какую бы книгу ты ни прочитал, получишь пользу. В какой бы день ты ни посетил меня, я окажу тебе почёт.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">أَسْمَاءُ الشَّرْطِ كُلُّهَا <span class="ar-tone-structure">مَبْنِيَّةٌ</span> مَا عَدَا <span class="ar-tone-subject">أَيًّا</span> فَهِيَ <span class="ar-tone-structure">مُعْرَبَةٌ</span>.</span><p class="rule-study-text">Все условные имена неизменяемы, кроме «айй»: оно изменяется по синтаксической позиции.</p></div></div>', 1, 'rule', 'Условные средства ставят два глагола настоящего-будущего времени в джазм: первый называется глаголом условия, второй — ответом условия.', 'الْأَدَوَاتُ الَّتِي تَجْزِمُ فِعْلَيْنِ مُضَارِعَيْنِ تُسَمَّى أَدَوَاتِ الشَّرْطِ؛ يُسَمَّى الْفِعْلُ الْأَوَّلُ فِعْلَ الشَّرْطِ، وَالثَّانِي جَوَابَ الشَّرْطِ. أَسْمَاءُ الشَّرْطِ كُلُّهَا مَبْنِيَّةٌ مَا عَدَا أَيًّا فَهِيَ مُعْرَبَةٌ.'),
    ('Мединский курс (Том 3)', '15', 'أَنْوَاعُ فِعْلِ الشَّرْطِ وَجَوَابِهِ (виды глагола условия и его ответа)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يَأْتِي <span class="ar-tone-verb">فِعْلُ الشَّرْطِ</span> وَ<span class="ar-tone-verb">جَوَابُهُ</span> عَلَى أَرْبَعِ صُوَرٍ.</span><p class="rule-study-text">Глагол условия и его ответ встречаются в четырёх сочетаниях.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре сочетания</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصُّورَةُ</span><span class="rule-table-ru">сочетание</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ</span><span class="rule-table-ru">глагол условия</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ</span><span class="rule-table-ru">ответ условия</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">١</span><span class="rule-table-ru">первое</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مُضَارِعٌ</span><span class="rule-table-ru">настоящее-будущее время</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مُضَارِعٌ</span><span class="rule-table-ru">настоящее-будущее время</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَتَى تَأْتِ نَأْتِ.</span><span class="rule-table-ru">Когда ты придёшь, мы придём.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٢</span><span class="rule-table-ru">второе</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">مَاضٍ فِي مَحَلِّ جَزْمٍ</span><span class="rule-table-ru">прошедший глагол в синтаксическом месте джазма</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">مَاضٍ فِي مَحَلِّ جَزْمٍ</span><span class="rule-table-ru">прошедший глагол в синтаксическом месте джазма</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَنِ ٱجْتَهَدَ نَجَحَ.</span><span class="rule-table-ru">Кто усердствовал, тот преуспел.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٣</span><span class="rule-table-ru">третье</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَاضٍ</span><span class="rule-table-ru">прошедшее время</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مُضَارِعٌ</span><span class="rule-table-ru">настоящее-будущее время</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَنْ قَالَ الْحَقَّ يَنْجُ.</span><span class="rule-table-ru">Кто сказал правду, тот спасётся.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٤</span><span class="rule-table-ru">четвёртое; редкое</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مُضَارِعٌ</span><span class="rule-table-ru">настоящее-будущее время</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَاضٍ</span><span class="rule-table-ru">прошедшее время</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ.</span><span class="rule-table-ru">Кто выстоит Ночь предопределения с верой и надеждой на награду, тому будет прощено.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ وَإِنْ تَعُودُوا نَعُدْ ﴾</span><span class="rule-example-ru">«Если вы вернётесь, то и Мы вернёмся».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ إِنْ أَحْسَنْتُمْ أَحْسَنْتُمْ لِأَنْفُسِكُمْ ﴾</span><span class="rule-example-ru">«Если вы творите добро, то творите его для самих себя».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ مَنْ كَانَ يُرِيدُ حَرْثَ الْآخِرَةِ نَزِدْ لَهُ فِي حَرْثِهِ ﴾</span><span class="rule-example-ru">«Кто желает нивы Последней жизни, тому Мы увеличим его ниву».</span></div></div></div>', 2, 'rule', 'Шарх перечисляет четыре сочетания форм глагола условия и ответа: два настоящих-будущих, два прошедших, прошедший с настоящим-будущим и редкое обратное сочетание.', 'يَأْتِي فِعْلُ الشَّرْطِ وَجَوَابُهُ عَلَى أَرْبَعِ صُوَرٍ: مُضَارِعَانِ، أَوْ مَاضِيَانِ فِي مَحَلِّ جَزْمٍ، أَوْ مَاضٍ وَمُضَارِعٌ، أَوْ مُضَارِعٌ وَمَاضٍ وَهَذَا قَلِيلٌ.'),
    ('Мединский курс (Том 3)', '15', 'كَمِ الِاسْتِفْهَامِيَّةُ وَكَمِ الْخَبَرِيَّةُ (вопросительная и повествовательная كَمْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Определение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَمِ الِاسْتِفْهَامِيَّةُ</span><span class="rule-table-ru">вопросительная «сколько?»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يُسْتَفْهَمُ بِهَا عَنْ عَدَدٍ مُبْهَمٍ يُرَادُ تَعْيِينُهُ</span><span class="rule-table-ru">с её помощью спрашивают о неопределённом количестве, которое хотят установить</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كَمْ رِيَالًا مَعَكَ؟</span><span class="rule-table-ru">Сколько риалов у тебя?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَمِ الْخَبَرِيَّةُ</span><span class="rule-table-ru">повествовательная «сколько же; много»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُخْبِرُ عَنْ عَدَدٍ كَثِيرٍ مُبْهَمٍ، فَهِيَ بِمَعْنَى كَثِيرٍ</span><span class="rule-table-ru">сообщает о большом неопределённом количестве и имеет смысл «много»</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">كَمْ عَالِمٍ رَأَيْتُ!</span><span class="rule-table-ru">Сколько учёных я видел! То есть: я видел многих учёных.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَمِ الِاسْتِفْهَامِيَّةُ</span><span class="rule-table-ru">вопросительные примеры</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَمِ الْخَبَرِيَّةُ</span><span class="rule-table-ru">повествовательные примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كَمْ طَالِبًا نَجَحَ؟</span><span class="rule-table-ru">Сколько студентов преуспело?</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">كَمْ كِتَابٍ عِنْدَكَ!</span><span class="rule-table-ru">Сколько же книг у тебя!</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">بِكَمْ رِيَالًا ٱشْتَرَيْتَ الْكِتَابَ؟</span><span class="rule-table-ru">За сколько риалов ты купил книгу? Вариант с винительным падежом.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">كَمْ كُتُبٍ عِنْدَكَ!</span><span class="rule-table-ru">Сколько же книг у тебя!</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">بِكَمْ رِيَالٍ ٱشْتَرَيْتَ الْكِتَابَ؟</span><span class="rule-table-ru">За сколько риалов ты купил книгу? Допустимый вариант с родительным падежом.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">كَمْ مِنْ عَالِمٍ رَأَيْتُ!</span><span class="rule-table-ru">Скольких учёных я видел!</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-jarr" dir="rtl" lang="ar">﴿ وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا فَجَاءَهَا بَأْسُنَا بَيَاتًا أَوْ هُمْ قَائِلُونَ ﴾</span><span class="rule-example-ru">«Сколько селений Мы погубили! Наше наказание приходило к ним ночью или во время полуденного отдыха».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">В чём они совпадают</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْخَاصِّيَّةُ</span><span class="rule-table-ru">общее свойство</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">كِلْتَاهُمَا ٱسْمٌ</span><span class="rule-table-ru">обе являются именами</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْسَتَا حَرْفَيْنِ</span><span class="rule-table-ru">не являются частицами</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِلْتَاهُمَا مُبْهَمٌ</span><span class="rule-table-ru">обе имеют неопределённое количественное значение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يُوَضِّحُهُمَا التَّمْيِيزُ</span><span class="rule-table-ru">их значение уточняет тамйиз</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كِلْتَاهُمَا يَحْتَاجُ إِلَى تَمْيِيزٍ</span><span class="rule-table-ru">обе нуждаются в тамйизе</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">التَّمْيِيزُ يَذْكُرُ الْمَعْدُودَ</span><span class="rule-table-ru">тамйиз называет исчисляемое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِلْتَاهُمَا لَهُ الصَّدَارَةُ</span><span class="rule-table-ru">обе занимают начальную позицию</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَقَعَانِ فِي أَوَّلِ الْكَلَامِ</span><span class="rule-table-ru">они стоят в начале высказывания</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">В чём они различаются</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَجْهُ الْفَرْقِ</span><span class="rule-table-ru">основание различия</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَمِ الِاسْتِفْهَامِيَّةُ</span><span class="rule-table-ru">вопросительная</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَمِ الْخَبَرِيَّةُ</span><span class="rule-table-ru">повествовательная</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَوَابُ</span><span class="rule-table-ru">необходимость ответа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَحْتَاجُ إِلَى جَوَابٍ</span><span class="rule-table-ru">требует ответа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا تَحْتَاجُ إِلَى جَوَابٍ</span><span class="rule-table-ru">не требует ответа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عَدَدُ التَّمْيِيزِ</span><span class="rule-table-ru">число тамйиза</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَمْيِيزُهَا مُفْرَدٌ دَائِمًا</span><span class="rule-table-ru">тамйиз всегда в единственном числе</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">تَمْيِيزُهَا مُفْرَدٌ وَجَمْعٌ، وَالْإِفْرَادُ أَكْثَرُ</span><span class="rule-table-ru">тамйиз бывает в единственном и множественном числе; единственное употребляется чаще</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُ التَّمْيِيزِ</span><span class="rule-table-ru">падеж тамйиза</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَنْصُوبٌ، إِلَّا بَعْدَ حَرْفِ جَرٍّ فَيَجُوزُ النَّصْبُ وَالْجَرُّ، وَالنَّصْبُ أَكْثَرُ</span><span class="rule-table-ru">винительный; после предлога допустимы винительный и родительный, причём винительный употребляется чаще</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَجْرُورٌ بِالْإِضَافَةِ إِلَيْهَا أَوْ بِمِنْ</span><span class="rule-table-ru">родительный по идафе к «кам» либо после «мин»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор вариантов после предлога</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُكْمُ التَّمْيِيزِ</span><span class="rule-table-ru">разбор тамйиза</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">بِكَمْ رِيَالًا ٱشْتَرَيْتَ؟</span><span class="rule-table-ru">За сколько риалов ты купил?</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رِيَالًا: تَمْيِيزٌ مَنْصُوبٌ</span><span class="rule-table-ru">«риалан» — тамйиз в винительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">بِكَمْ رِيَالٍ ٱشْتَرَيْتَ؟</span><span class="rule-table-ru">За сколько риалов ты купил?</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">رِيَالٍ: اِسْمٌ مَجْرُورٌ بِمِنْ مُقَدَّرَةٍ، وَقِيلَ مَجْرُورٌ بِالْإِضَافَةِ</span><span class="rule-table-ru">«рийалин» — имя в родительном падеже после подразумеваемого «мин»; также сказано: по идафе</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Вопросительная «кам» спрашивает о неопределённом количестве, а повествовательная сообщает о большом неопределённом количестве; шарх сопоставляет их управление тамйизом.', 'كَمِ الِاسْتِفْهَامِيَّةُ يُسْتَفْهَمُ بِهَا عَنْ عَدَدٍ مُبْهَمٍ يُرَادُ تَعْيِينُهُ، وَكَمِ الْخَبَرِيَّةُ تُخْبِرُ عَنْ عَدَدٍ كَثِيرٍ مُبْهَمٍ. كِلْتَاهُمَا ٱسْمٌ مُبْهَمٌ يَحْتَاجُ إِلَى تَمْيِيزٍ وَلَهُ الصَّدَارَةُ.'),
    ('Мединский курс (Том 3)', '15', 'حَتَّى: انْتِهَاءُ الْغَايَةِ وَالتَّعْلِيلُ (предел и цель с حَتَّى)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Два значения حَتَّى</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَفْسِيرُهُ</span><span class="rule-table-ru">русское объяснение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">انْتِهَاءُ الْغَايَةِ</span><span class="rule-table-ru">предел</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بِمَعْنَى إِلَى</span><span class="rule-table-ru">в значении «до»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَأَدْرُسُ حَتَّى تَغْرُبَ الشَّمْسُ.</span><span class="rule-table-ru">Я буду заниматься, пока не зайдёт солнце; то есть до захода солнца.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">انْتِهَاءُ الْغَايَةِ</span><span class="rule-table-ru">предел</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بِمَعْنَى إِلَى</span><span class="rule-table-ru">в значении «до»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا يَدْخُلْ أَحَدٌ حَتَّى يَسْتَأْذِنَ.</span><span class="rule-table-ru">Пусть никто не входит, пока не попросит разрешения.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْلِيلُ</span><span class="rule-table-ru">цель или причина</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بِمَعْنَى كَيْ</span><span class="rule-table-ru">в значении «чтобы»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلْتُ بِهُدُوءٍ حَتَّى لَا أَشْغَلَكَ.</span><span class="rule-table-ru">Я вошёл тихо, чтобы не отвлекать тебя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْلِيلُ</span><span class="rule-table-ru">цель или причина</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بِمَعْنَى كَيْ</span><span class="rule-table-ru">в значении «чтобы»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَجْتَهِدُ حَتَّى أَنْجَحَ بِتَقْدِيرٍ مُمْتَازٍ.</span><span class="rule-table-ru">Я усердствую, чтобы преуспеть с отличной оценкой.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пример из хадиса</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّصُّ</span><span class="rule-table-ru">текст и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.</span><span class="rule-table-ru">Не уверует никто из вас, пока не станет желать своему брату того же, чего желает самому себе.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ هُمُ الَّذِينَ يَقُولُونَ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ حَتَّى يَنْفَضُّوا ﴾</span><span class="rule-example-ru">«Они говорят: не расходуйте на тех, кто находится возле Посланника Аллаха, пока они не разойдутся».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يُنْصَبُ الْفِعْلُ الْمُضَارِعُ بَعْدَ <span class="ar-tone-particle">حَتَّى</span> بِـ<span class="ar-tone-particle">أَنْ</span> مُضْمَرَةٍ وُجُوبًا.</span><p class="rule-study-text">Глагол настоящего-будущего времени после «хатта» ставится в винительное состояние скрытой обязательной частицей «ан».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор أَجْتَهِدُ حَتَّى أَنْجَحَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَجْتَهِدُ</span><span class="rule-table-ru">я усердствую</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">глагол настоящего-будущего времени в именительном состоянии; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ</span><span class="rule-table-ru">исполнитель — скрытое местоимение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَتَّى</span><span class="rule-table-ru">до; чтобы</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">предлог, построенный на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">حَرْفُ جَرٍّ</span><span class="rule-table-ru">предлог</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْجَحَ</span><span class="rule-table-ru">я преуспею</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِأَنْ مُضْمَرَةٍ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">глагол настоящего-будущего времени в винительном состоянии из-за скрытой «ан»; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ مُضْمَرَةٌ وُجُوبًا</span><span class="rule-table-ru">«ан» обязательно скрыта</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ</span><span class="rule-table-ru">развёрнутый масдар</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مِنْ أَنْ مُضْمَرَةٍ وَالْفِعْلِ أَنْجَحَ فِي مَحَلِّ جَرٍّ بِحَرْفِ الْجَرِّ حَتَّى.</span><span class="rule-table-ru">из скрытой «ан» и глагола «анджаха»; находится в синтаксическом месте родительного падежа после «хатта»</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">فِي مَحَلِّ جَرٍّ</span><span class="rule-table-ru">в синтаксическом месте родительного падежа</span></td></tr></tbody></table></div></div></div>', 4, 'rule', '«Хатта» выражает предел со значением «до» либо цель со значением «чтобы»; следующий глагол ставится в насб скрытой обязательной частицей «ан».', 'حَتَّى حَرْفُ جَرٍّ لَهُ مَعْنَيَانِ: انْتِهَاءُ الْغَايَةِ بِمَعْنَى إِلَى، وَالتَّعْلِيلُ بِمَعْنَى كَيْ. يُنْصَبُ الْفِعْلُ الْمُضَارِعُ بَعْدَهَا بِأَنْ مُضْمَرَةٍ وُجُوبًا، وَالْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ جَرٍّ بِحَتَّى.'),
    ('Мединский курс (Том 3)', '15', 'اِسْمُ الْفِعْلِ هَا (имя действия повеления هَا — «возьми»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">هَا</span> ٱسْمُ فِعْلِ أَمْرٍ بِمَعْنَى <span class="ar-tone-verb">خُذْ</span>.</span><p class="rule-study-text">«Ха» — имя действия повеления со значением «возьми».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Формы, приведённые автором</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاءَ</span><span class="rule-table-ru">возьми — обращение к мужчине</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خُذْ أَنْتَ</span><span class="rule-table-ru">возьми ты, мужчина</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاءِ</span><span class="rule-table-ru">возьми — обращение к женщине</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خُذِي أَنْتِ</span><span class="rule-table-ru">возьми ты, женщина</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاؤُمَا</span><span class="rule-table-ru">возьмите — обращение к двоим</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خُذَا أَنْتُمَا</span><span class="rule-table-ru">возьмите вы двое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاؤُمْ</span><span class="rule-table-ru">возьмите — обращение к группе мужчин</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خُذُوا أَنْتُمْ</span><span class="rule-table-ru">возьмите вы, мужчины</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاؤُنَّ</span><span class="rule-table-ru">возьмите — обращение к группе женщин</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خُذْنَ أَنْتُنَّ</span><span class="rule-table-ru">возьмите вы, женщины</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ هَاؤُمُ ٱقْرَءُوا كِتَابِيَهْ ﴾</span><span class="rule-example-ru">«Возьмите и прочтите мою книгу».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примечание автора</span><p class="rule-study-text"><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْمِيمُ فِي الْآيَةِ حُرِّكَتْ بِالضَّمِّ مَنْعًا مِنِ الْتِقَاءِ السَّاكِنَيْنِ.</span> Мим в аяте получила дамму, чтобы избежать встречи двух сукунов.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор هَاءَ الْكِتَابَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاءَ</span><span class="rule-table-ru">возьми</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْمُ فِعْلِ أَمْرٍ مَبْنِيٌّ عَلَى الْفَتْحِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ وُجُوبًا تَقْدِيرُهُ أَنْتَ.</span><span class="rule-table-ru">имя действия повеления, построенное на фатхе; исполнитель — обязательно скрытое местоимение «ты»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْمُ فِعْلِ أَمْرٍ</span><span class="rule-table-ru">имя действия повеления</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْكِتَابَ</span><span class="rule-table-ru">книгу</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">прямое дополнение в винительном падеже; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор هَاؤُمْ إِعْلَانًا</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَاؤُمْ</span><span class="rule-table-ru">возьмите</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْمُ فِعْلِ أَمْرٍ مَبْنِيٌّ عَلَى السُّكُونِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ وُجُوبًا تَقْدِيرُهُ أَنْتُمْ.</span><span class="rule-table-ru">имя действия повеления, построенное на сукуне; исполнитель — обязательно скрытое местоимение «вы»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْمُ فِعْلِ أَمْرٍ</span><span class="rule-table-ru">имя действия повеления</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">إِعْلَانًا</span><span class="rule-table-ru">объявление</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">прямое дополнение в винительном падеже; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td></tr></tbody></table></div></div></div>', 5, 'rule', 'Имя действия повеления «ха» имеет значение «возьми», изменяет форму по адресату и управляет прямым дополнением в винительном падеже.', 'هَا ٱسْمُ فِعْلِ أَمْرٍ بِمَعْنَى خُذْ. يَجُوزُ أَنْ يُقَالَ: هَاءَ، وَهَاءِ، وَهَاؤُمَا، وَهَاؤُمْ، وَهَاؤُنَّ. وَيَعْمَلُ عَمَلَ فِعْلِ الْأَمْرِ فَيَنْصِبُ الْمَفْعُولَ بِهِ.'),
    ('Мединский курс (Том 3)', '15', 'حَذْفُ نُونِ يَكُنْ (удаление нуна в يَكُنْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يَجُوزُ حَذْفُ نُونِ <span class="ar-tone-verb">يَكُنْ</span> فِي حَالَةِ <span class="ar-tone-jazm">الْجَزْمِ</span>.</span><p class="rule-study-text">В состоянии джазма нун в форме «якун» разрешается удалить.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-jazm" dir="rtl" lang="ar">﴿ وَلَمْ أَكُ بَغِيًّا ﴾</span><span class="rule-example-ru">«И я не была распутницей».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры разрешённого удаления</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تَكُ ظَالِمًا.</span><span class="rule-table-ru">Не будь несправедливым.</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">تَكُ</span><span class="rule-table-ru">форма без нуна</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ يَكُ حَامِدٌ مَرِيضًا.</span><span class="rule-table-ru">Хамид не был болен.</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">يَكُ</span><span class="rule-table-ru">форма без нуна</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يَمْتَنِعُ حَذْفُ النُّونِ فِي حَالَتَيْنِ: إِذَا كَانَ مَا بَعْدَهَا <span class="ar-tone-structure">سَاكِنًا</span>، أَوْ <span class="ar-tone-nasb">ضَمِيرَ نَصْبٍ مُتَّصِلًا</span>.</span><p class="rule-study-text">Удаление нуна невозможно в двух случаях: если следующее слово начинается с сукуна либо если после формы стоит присоединённое объектное местоимение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два случая запрета</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَبَبُ بَقَاءِ النُّونِ</span><span class="rule-table-ru">почему нун сохраняется</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا بَعْدَهَا سَاكِنٌ</span><span class="rule-table-ru">после неё стоит начальный сукун</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ يَكُنِ الرَّجُلُ قَائِمًا.</span><span class="rule-table-ru">Мужчина не стоял.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَعْدَهَا سَاكِنٌ</span><span class="rule-table-ru">за ней следует сукун</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">بَعْدَهَا ضَمِيرُ نَصْبٍ مُتَّصِلٌ</span><span class="rule-table-ru">после неё присоединённое объектное местоимение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِنْ يَكُنْهُ فَلَنْ تُسَلَّطَ عَلَيْهِ.</span><span class="rule-table-ru">Если это он, тебе не будет дана власть над ним.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْهَاءُ ضَمِيرُ نَصْبٍ مُتَّصِلٌ</span><span class="rule-table-ru">ха — присоединённое объектное местоимение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-jazm" dir="rtl" lang="ar">﴿ لَمْ يَكُنِ الَّذِينَ كَفَرُوا ... ﴾</span><span class="rule-example-ru">«Не были те, которые не уверовали…».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор لَا تَكُ ظَالِمًا</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا</span><span class="rule-table-ru">не</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">حَرْفُ نَهْيٍ وَجَزْمٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица запрета и джазма, построенная на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَهْيٍ وَجَزْمٍ</span><span class="rule-table-ru">частица запрета и джазма</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَكُ</span><span class="rule-table-ru">будь</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَجْزُومٌ، وَعَلَامَةُ جَزْمِهِ السُّكُونُ عَلَى النُّونِ الْمَحْذُوفَةِ.</span><span class="rule-table-ru">глагол настоящего-будущего времени в джазме; признак — сукун на удалённом нуне</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمُ تَكُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنْتَ</span><span class="rule-table-ru">имя «таку» — скрытое местоимение «ты»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَالِمًا</span><span class="rule-table-ru">несправедливым</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">خَبَرُ تَكُ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">сказуемое «таку» в винительном падеже; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ تَكُ</span><span class="rule-table-ru">сказуемое «таку»</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'Нун глагола «якун» можно удалить в джазме, но нельзя удалять перед словом с начальным сукуном или перед присоединённым объектным местоимением.', 'يَجُوزُ حَذْفُ نُونِ يَكُنْ فِي حَالَةِ الْجَزْمِ، وَيَمْتَنِعُ حَذْفُهَا إِذَا كَانَ مَا بَعْدَهَا سَاكِنًا، أَوْ كَانَ مَا بَعْدَهَا ضَمِيرَ نَصْبٍ مُتَّصِلًا.'),
    ('Мединский курс (Том 3)', '15', 'التَّصْغِيرُ (уменьшительная форма)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">لِلتَّصْغِيرِ <span class="ar-tone-structure">ثَلَاثَةُ أَوْزَانٍ</span>: <span class="ar-tone-verb">فُعَيْلٌ، فُعَيْعِلٌ، فُعَيْعِيلٌ</span>.</span><p class="rule-study-text">У уменьшительной формы три веса: фу‘айль, фу‘ай‘иль и фу‘ай‘иль с долгой йа.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три веса</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">вес</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا يُصَغَّرُ بِهِ</span><span class="rule-table-ru">к каким именам применяется</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">все примеры шарха с переводом</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فُعَيْلٌ</span><span class="rule-table-ru">фу‘айль</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الثُّلَاثِيُّ</span><span class="rule-table-ru">трёхбуквенное имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَلَمٌ: قُلَيْمٌ؛ جَبَلٌ: جُبَيْلٌ؛ عَبْدٌ: عُبَيْدٌ؛ حَسَنٌ: حُسَيْنٌ.</span><span class="rule-table-ru">ручка — маленькая ручка; гора — холмик; раб — маленький раб; Хасан — Хусейн</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فُعَيْعِلٌ</span><span class="rule-table-ru">фу‘ай‘иль</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الرُّبَاعِيُّ</span><span class="rule-table-ru">четырёхбуквенное имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فُنْدُقٌ: فُنَيْدِقٌ؛ زَيْنَبُ: زُيَيْنِبُ؛ كِتَابٌ: كُتَيِّبٌ؛ شَدِيدٌ: شُدَيِّدٌ.</span><span class="rule-table-ru">гостиница — маленькая гостиница; Зайнаб — Зуьяйниб; книга — книжечка; сильный — уменьшительная форма</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فُعَيْعِيلٌ</span><span class="rule-table-ru">фу‘ай‘иль с долгой йа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الْخُمَاسِيُّ الَّذِي رَابِعُهُ حَرْفُ عِلَّةٍ</span><span class="rule-table-ru">пятибуквенное имя, четвёртая буква которого слабая</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِفْتَاحٌ: مُفَيْتِيحٌ؛ فِنْجَانٌ: فُنَيْجِينٌ؛ دِينَارٌ: دُنَيْنِيرٌ؛ عُصْفُورٌ: عُصَيْفِيرٌ.</span><span class="rule-table-ru">ключ — маленький ключ; чашка — маленькая чашка; динар — маленький динар; воробей — маленький воробей</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يُصَغَّرُ الِاسْمُ <span class="ar-tone-raf">بِضَمِّ أَوَّلِهِ</span>، وَ<span class="ar-tone-nasb">فَتْحِ ثَانِيهِ</span>، وَ<span class="ar-tone-structure">زِيَادَةِ يَاءٍ سَاكِنَةٍ بَعْدَ الْحَرْفِ الثَّانِي الْمَفْتُوحِ</span>.</span><p class="rule-study-text">Для образования уменьшительной формы первая буква получает дамму, вторая — фатху, а после второй открытой буквы добавляется йа с сукуном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Название добавленной буквы</span><p class="rule-study-text"><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">هَذِهِ الْيَاءُ تُسَمَّى يَاءَ التَّصْغِيرِ.</span> Эта йа называется йа уменьшения.</p></div></div>', 7, 'rule', 'Шарх даёт три веса уменьшительной формы и общее построение: дамма первой буквы, фатха второй и добавочная неподвижная йа после второй буквы.', 'لِلتَّصْغِيرِ ثَلَاثَةُ أَوْزَانٍ: فُعَيْلٌ لِلِاسْمِ الثُّلَاثِيِّ، وَفُعَيْعِلٌ لِلِاسْمِ الرُّبَاعِيِّ، وَفُعَيْعِيلٌ لِلِاسْمِ الْخُمَاسِيِّ الَّذِي رَابِعُهُ حَرْفُ عِلَّةٍ. يُصَغَّرُ الِاسْمُ بِضَمِّ أَوَّلِهِ، وَفَتْحِ ثَانِيهِ، وَزِيَادَةِ يَاءٍ سَاكِنَةٍ بَعْدَ الْحَرْفِ الثَّانِي الْمَفْتُوحِ، وَتُسَمَّى يَاءَ التَّصْغِيرِ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'جَوَازِمُ الْمُضَارِعِ
الْجَازِمُ فِعْلَيْنِ
الأَدَوَاتُ التي تَجْزِمُ فعلين مُضَارعين تُسَمَّى أدواتِ الشَّرْطِ . ويُسَمَّى الفعلُ الأوَّلُ فعلَ الشَّرط ، والثَّانِي جَوَابَ الشَّرط . وهذه الأدوات يُبَيِّنُهَا الجدول الآتي :
أداة الشرط
نوعها
الأمثلة
إِنْ
حرف
قال تعالى : ﴿ وَإِنْ تَعُودُوا نَعُدْ ﴾
ونحو : إن تزرْني أَزُرْكَ .
إِذْمَا
حرف
إِذْمَا تَقُمْ أَقُمْ .
مَنْ
اسم للعاقل
قال تعالى : ﴿ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ﴾
ونحو : من يَغِبْ يُطْوَ قَيْدُهُ .
ما
اسم
لغير العاقل
قال تعالى : ﴿ وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ ﴾ ، ونحو : ما تَزْرَعْ تَحْصُدْ .
مَهْمَا
اسم لغير العاقل
مَهْمَا تَقُلْ أُصَدَّقْكَ ، ونحو : مهما تَقْرَأْ أَقْرَأْ .
مَتَى
اسم	للزمان
مَتَى تُسَافِرْ أُسَافِرْ
أَيْنَ
اسم للمكان
قال تعالى : ﴿ أَيْنَمَا تَكُونُوا يُدْرِكْكُمُ الْمَوْتُ ﴾ ، ونحو : أينما تُسَافِرْ أُسَافرْ .
* تَتَّصِل بها كثيراً ( ما ) الزّائدة للتوكيد .
حَيْثُ
اسم للمكان
حَيْثُمَا تَذْهَبْ يَرَك اللهُ.
* لا تجزم إلا إذا اتَّصَلَتْ بها (ما ) الزّائدة .
أَيّ
اسم بحسَب ما تضاف إليه
أيُّ طالبٍ يجتهدْ ينجحْ . أيَّ كتابٍ تقرأْ تَسْتَفِدْ .
في أيَّ يومٍ تزرْني أُكْرِمْك .
* أسماءُ الشَّرطِ كلُّها مبنيَّّة ما عدا ( أيّ ) فمُعْرَبَةٌ .', 60, 60, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أنواعُ فعلِ الشَّرطِ ، والجوابِ :
1- مُضَارِعَانِ ، نحو قوله تعالى : ﴿ وَإِنْ تَعُودُوا نَعُدْ ﴾ ونحو : مَتَى تَأْتِ نَأْتِ .
2- مَاضِيَانِ ( في محل جزم ) نحو : قوله تعالى: ﴿ إِنْ أَحْسَنْتُمْ أَحْسَنْتُمْ لِأَنْفُسِكُمْ ﴾ .
ونحو : مَن اجتهدَ نجحَ .
3- مَاضٍ ، ومُضارع ، نحو قوله تعالى : ﴿ مَنْ كَانَ يُرِيدُ حَرْثَ الآخِرَةِ نَزِدْ لَهُ فِي حَرْثِهِ ﴾ ونحو : مَنْ قالَ الحقَّ يَنْجُ .
4- مُضَارِعٌ ، وماضٍ ( وهذا قليل ) نحو قوله ﷺ : " مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيَماناً وَاحْتِسَاباً
غُفِرَ له " .', 61, 61, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'كَم الاسْتِفْهَامِيَّةُ ، وكَم الْخَبَرِيَّةُ
كَم الاستفهاميَّةُ ، هي: التي يُسْتَفْهَمُ بها عن عَدَدٍ مُبْهَمٍ يُرَادُ تَعْيِينُه ، نحو: كم ريالاً معك؟
كم طالباً نجحَ ؟ بكم ريالاً اشتريتَ الكتابَ ؟ بكم ريالٍ اشتريتَ الكتابَ ؟
كَم الخبريَّةُ ، هي : التي تُخْبِرُ عن عددٍ كثيرٍ مُبْهَم . فهي بمعنى (كَثير ) نحو :            كم عالمٍ رأيتُ ! أي : رأيتُ كثيراً من العلماء .
ونحو : كم كتابٍ عندك ! كم كتُبٍ عندك ! قال تعالى : ﴿ وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا فَجَاءَهَا بَأْسُنَا بَيَاتًا أَوْ هُمْ قَائِلُونَ ﴾ .
* تَتَّفِقُ كم الاستفهاميةُ ، والخبريّةُ فيما يلي :
1- كلاهما اسمٌ             2- كلاهما مُبْهَمٌ              3- كلاهما يحتاج إلى تَمْيِيزٍ .
4- كلاهما له الصَّدَارةُ ، أي : يَقَعَانِ في أوَّل الكلام .
* وتَخْتَلِفَانِ في أمورٍ يوضَّحُها الجدولُ الآتي :
كم الاستفهاميَّةُ
كم الخبريَّةُ
1- تحتاج إلى جواب
لا تحتاج إلى جواب
2- تمييزها مُفرد دائماً .
تمييزها مُفرد ، وجَمْع . والإفراد أكثر .
3- تمييزها منصوبٌ إلاّ إذا سُبِقَتْ بحرف جر فيجوز النّصب والجر ( والنّصب أكثر ) نحو : كم طالباً في الفصل ؟   بكم ريالاً اشتريتَ ؟
تمييز منصوب              تمييز منصوب
ويجوز : بكم ريالٍ اشتريتَ ؟
اسم مجرور بـ ( مِنْ ) مُقَدَّرة .
وقيل : مجرور بالإضافة .
تمييزها مجرورٌ بالإضافة إليها ، أو مجرور بـ ( مِنْ ) نحو : كم كتابٍ قرأتَ !     كم كُتُبٍ قرأتَ!
مضاف إليه مجرور	      مضاف إليه مجرور
كم مِنْ عالمٍ رأيتُ !
اسم مجرور بـ ( مِنْ )', 61, 62, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15' and sort_order = 3;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'حَتَّى
حَتَّى : حرفُ جَرًّ له مَعْنَيَانِ ، هما :
1- انْتِهَاءُ الْغَايَةِ ( بمعنى إِلَى ) نحو : سأدرسُ حتى تَغْرُبَ الشَّمْسُ ، أي : إلى أَنْ تَغْرُبَ
الشَّمسُ . ونحو : لا يدخلْ أحدٌ حتى يَسْتَأْذِنَ .
قال ﷺ : " لاَ يُؤْمِنُ أحَدُكُمْ حَتَّى يُحِبَّ لأَِخِيهِ مَا يُحِبُّ لِنَفْسِهِ " .
2- التَّعْلِيلُ ( بمعنى كَيْ ) نحو : دخلتُ بهدوءٍ حَتَّى لا أَشْغَلَكَ ، أي : لِكَيْلاَ أَشْغَلَكَ .
ونحو : أجتهدُ حتى أنجحَ بتقدير مُمتاز .
قال تعالى: ﴿ هُمُ الَّذِينَ يَقُولُونَ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ حَتَّى يَنْفَضُّوا ﴾ .
* يُنْصَبُ الفعلُ المضارع بعد حتى بـ ( أَنْ ) مضمرة وجوباً .
الإعراب : أجتهدُ حَتَّى أنجحَ .
أجتهدُ : فعل مضارع مرفوع وعلامة رفعه الضمة الظاهرة .
حتَّى : حرف جر مبني على السكون لا محل له من الإعراب .
أنجحَ : فعل مضارع منصوب بأن مضمرة وعلامة نصبه الفتحة الظاهرة.
والمصدر المؤوَّل ( مِنْ أَنْ المضمرة والفعل أنجحَ ) في محلَّ جرّ بحرف الجرَّ حَتَّى .', 62, 63, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15' and sort_order = 4;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'اسمُ الفعلِ ( هَا )
هَا : اسمُ فعلِ أَمْرٍ ، بمعنى : خُذْ ، نحو : هَا الكِتابَ ، بمعنى : خُذِ الكتابَ .
* يجوز أن تقولَ : هَاءَ الكتابَ ، وهَاءِ ، وهَاؤُمَا ، وهَاؤُمْ ، وهَاؤُنَّ .
قال تعالى: ﴿ هَاؤُمُ اقْرَءُوا كِتَابِيَهْ ﴾ الميم في الآية حُرَّكَتْ بالضَّمَّ منعاً مِنْ التقاء السَّاكِنَيْنِ.
الإعراب : هَاءَ الكتابَ .
هَاءَ : اسم فعل أمر مبني على الفتح ، والفاعل ضمير مستتر وجوبا تقديره: أنتَ.
الكتابَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة .
* هَاؤُمْ إعلاناً .
هَاؤُمْ : اسم فعل أمر مبني على السكون، والفاعل ضمير مستتر وجوبا، تقديره: أنتم.
إعلاناً : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة .', 63, 63, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '15' and sort_order = 5;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'حَذْفُ نُونِ ( يَكُنْ )
يجوزُ حذفُ نونِ ( يَكُنْ ) في حالة الجزم ، نحو قوله تعالى : ﴿ وَلَمْ أَكُ بَغِيًّا ﴾ .
ونحو : لا تَكُ ظالماً . لم يَكُ حامدٌ مريضاً .
* يَمْتَنعُ حذفُ النُّونِ في حالتين ، هما :
1- إذا كان ما بعدها ساكن ، قال تعالى : ﴿ لَمْ يَكُنِ الَّذِينَ كَفَرُوا ... ﴾ .
ونحو : لم  يكنِ اْلرَّجُلُ قائماً .
2- إذا كان ما بعدها ضمير نصب مُتَّصِل ، نحو قوله ﷺ : " إِنْ يَكُنْهُ فَلَنْ تُسَلَّطَ عَلَيْهِ ".
الإعراب : لا تَكُ ظالماً .
لا : حرف نهي وجزم مبني على السكون لا محلَّ له من الإعراب .
